    public function __construct(private PDO $db,callable $store){$this->store=$store;}
    private function insert(string $table,string $id,array $values):int{
        foreach([$table,$id,...array_keys($values)] as $name)if(!preg_match('/^[a-z_][a-z0-9_]*$/D',$name))throw new LogicException('Invalid seed identifier.');
        $q=$this->db->prepare('INSERT INTO '.$table.' ('.implode(',',array_keys($values)).') VALUES ('.implode(',',array_fill(0,count($values),'?')).') RETURNING '.$id);$q->execute(array_values($values));return (int)$q->fetchColumn();
    }
    private function photo(int $owner,string $purpose,?int $order,string $asset,string $batch):array{
        $meta=($this->store)($asset);$key=$meta['object_key'];$this->files[]=$key;
        $id=$this->insert('private_files','file_id',['owner_id'=>$owner,'order_id'=>$order,'purpose'=>$purpose,'object_key'=>$key,'original_name'=>'DEMO-'.$batch.'-'.$asset.'.png','mime_type'=>'image/png','byte_size'=>$meta['byte_size'],'checksum_sha256'=>$meta['checksum_sha256'],'storage_backend'=>'supabase','storage_bucket'=>$meta['bucket'],'delete_after'=>(new DateTimeImmutable('+180 days'))->format(DATE_ATOM)]);
        return ['file_id'=>$id]+$meta;
    }
