        $admin=(int)$this->db->query("SELECT u.user_id FROM users u JOIN user_roles ur USING(user_id) JOIN roles r USING(role_id) WHERE r.role_code='ADMIN' AND u.account_status='ACTIVE' ORDER BY u.user_id LIMIT 1")->fetchColumn();
