        if(!$policy||$policy['calculation_rule']!=='BASE_PLUS_DISTANCE_PLUS_WEIGHT')throw new RuntimeException('Configured distance/weight pricing required.');
        $category=(int)$this->db->query("SELECT category_id FROM parcel_categories WHERE active AND restriction_type='ALLOWED' ORDER BY category_id LIMIT 1")->fetchColumn();if(!$category)throw new RuntimeException('An allowed parcel category is required.');
        $defs=['customer'=>['CUSTOMER','DEMO - Khách Mai','vi','VN'],'customer_en'=>['CUSTOMER','DEMO - Customer Alex','en','US'],'an'=>['SHIPPER','DEMO - Shipper An','vi','VN'],'binh'=>['SHIPPER','DEMO - Shipper Bình','vi','VN'],'chi'=>['SHIPPER','DEMO - Shipper Chi','vi','VN'],'dung'=>['SHIPPER','DEMO - Shipper Dũng','vi','VN'],'hanh'=>['SHIPPER','DEMO - Shipper Hạnh','vi','VN'],'kyc'=>['SHIPPER','DEMO - Hồ sơ Linh','vi','VN']];
