            $customerKey=$n%5===0?'customer_en':'customer';$customer=$users[$customerKey];$pickup=$places[$n%count($places)];$drop=$places[($n+2)%count($places)];
            $distance=number_format(2.4+($n%8)*0.75,3,'.','');$weight=number_format(0.5+($n%6)*0.8,3,'.','');$components=DistanceWeightPrice::components($policy,$distance,$weight);$total=DistanceWeightPrice::ceil($components['subtotal_minor']);
            $components+=['time_multiplier'=>'1','weather_multiplier'=>'1','total_charge_minor'=>$total,'return_fee_minor'=>(string)$policy['return_fee_minor']];
            $closed=in_array($status,['DELIVERED','RETURNED','CANCELLED'],true);$days=$closed?($n<18?$n%14:($n===18?20:($n===19?31:$n%10))):0;
