            $paid=$status!=='PENDING_PAYMENT'&&!(($status==='CANCELLED')&&$n%2===0);$code='DEMO-'.substr($batch,4).'-'.str_pad((string)($n+1),3,'0',STR_PAD_LEFT);
            $snapshot=['demo'=>true,'source'=>'FICTIONAL_SCREENSHOT_DATA','currency_code'=>'VND','app_language'=>$defs[$customerKey][2],'pricing_policy_id'=>$policy['pricing_policy_id'],'pricing_policy_version'=>$policy['config_version'],'calculation_rule'=>$policy['calculation_rule'],'components'=>$components,'context'=>['distance_km'=>$distance,'duration_minutes'=>18+$n%12,'weather_condition'=>'NORMAL','provider'=>'DEMO-SIMULATED','observed_at'=>$at],'parcel'=>['category_id'=>$category,'description'=>'DEMO - '.(['Tài liệu hợp đồng','Hộp quà lưu niệm','Sách và dụng cụ học tập','Đồ dùng văn phòng'][$n%4]),'weight_kg'=>$weight],'cancellation_fees'=>['PENDING_PAYMENT'=>'0','SEARCHING_SHIPPER'=>'0','NO_SHIPPER_FOUND'=>'0']];
