            $timeline=['PENDING_PAYMENT'];if($paid)$timeline[]='SEARCHING_SHIPPER';if($shipperKey)$timeline[]='SHIPPER_ASSIGNED';if(in_array($status,['PICKED_UP','IN_DELIVERY','RETURNING','RETURNED','DELIVERED'],true))$timeline[]='PICKED_UP';if(in_array($status,['IN_DELIVERY','RETURNING','RETURNED','DELIVERED'],true))$timeline[]='IN_DELIVERY';if(in_array($status,['RETURNING','RETURNED'],true))$timeline[]='RETURNING';if(!in_array($status,$timeline,true))$timeline[]=$status;
            $old=null;foreach($timeline as $step=>$state){$this->insert('order_status_history','status_history_id',['order_id'=>$oid,'old_status'=>$old,'new_status'=>$state,'actor_kind'=>'SYSTEM','note'=>'DEMO - imported fictional timeline','created_at'=>$created->modify('+'.($step*5).' minutes')->format(DATE_ATOM)]);$old=$state;}
            if($paid&&in_array($status,['CANCELLED','RETURNED'],true))$this->insert('refunds','refund_id',['payment_id'=>$pid,'order_id'=>$oid,'reason'=>$status==='RETURNED'?'RETURN_FEE_DEDUCTION':'CUSTOMER_CANCELLATION','gross_amount_minor'=>$total,'deducted_fee_minor'=>$status==='RETURNED'?$policy['return_fee_minor']:0,'refund_amount_minor'=>$status==='RETURNED'?bcsub($total,(string)$policy['return_fee_minor'],0):$total,'currency_code'=>'VND','provider'=>'DEMO','status'=>'SUCCEEDED','provider_refund_id'=>'DEMO-NOT-A-REFUND-'.$code,'evidence_reference'=>'DEMO - simulated fixture, no funds moved','request_key'=>'demo-refund-'.$batch.'-'.$n,'created_at'=>$at,'completed_at'=>$ended]);
