            $did=$this->insert('deliveries','delivery_id',['order_id'=>$oid,'assignment_id'=>$aid,'picked_up_at'=>$status==='SHIPPER_ASSIGNED'?null:$created->modify('+12 minutes')->format(DATE_ATOM),'delivery_started_at'=>in_array($status,['IN_DELIVERY','RETURNING','RETURNED','DELIVERED'],true)?$created->modify('+17 minutes')->format(DATE_ATOM):null,'delivered_at'=>$status==='DELIVERED'?$ended:null,'return_started_at'=>in_array($status,['RETURNING','RETURNED'],true)?$created->modify('+20 minutes')->format(DATE_ATOM):null,'returned_at'=>in_array($status,['RETURNING','RETURNED'],true)?$created->modify('+23 minutes')->format(DATE_ATOM):null,'customer_return_confirmed_at'=>$status==='RETURNED'?$ended:null,'failure_reason_code'=>in_array($status,['RETURNING','RETURNED'],true)?'RECIPIENT_ABSENT':null,'failure_note'=>in_array($status,['RETURNING','RETURNED'],true)?'DEMO - người nhận vắng mặt':null,'created_at'=>$at,'updated_at'=>$ended??$at]);
            if(in_array($status,['DELIVERED','RETURNED','RETURNING'],true)){$photo=$this->photo($shipper['id'],'EVIDENCE',$oid,$status==='DELIVERED'?'delivery':'return',$batch);$this->insert('delivery_evidence','evidence_id',['delivery_id'=>$did,'evidence_type'=>$status==='DELIVERED'?'DELIVERY_PHOTO':'RETURN_PHOTO','object_key'=>$photo['object_key'],'mime_type'=>'image/png','byte_size'=>$photo['byte_size'],'checksum_sha256'=>$photo['checksum_sha256'],'uploaded_by'=>$shipper['id'],'uploaded_at'=>$ended??$at,'delete_after'=>(new DateTimeImmutable('+90 days'))->format(DATE_ATOM)]);}
            if($closed&&$status!=='CANCELLED'){
