                $eid=$this->insert('shipper_earnings','earning_id',['order_id'=>$oid,'shipper_id'=>$shipper['id'],'earning_type'=>$status==='DELIVERED'?'SUCCESSFUL_DELIVERY':'FAILED_RETURN','basis_amount_minor'=>$total,'percentage_rate'=>$status==='DELIVERED'?'80.0000':null,'gross_amount_minor'=>$amount,'currency_code'=>'VND','payout_status'=>$paidOut?'PAID':'PENDING','policy_snapshot'=>json_encode(['demo'=>true,'percentage_rate'=>$status==='DELIVERED'?80:null,'fixed_amount_minor'=>$status==='RETURNED'?10000:null,'not_a_real_transfer'=>true]),'created_at'=>$ended]);
                $this->insert('shipper_payouts','payout_id',['earning_id'=>$eid,'shipper_id'=>$shipper['id'],'bank_account_id'=>$banks[$shipperKey],'source_amount_minor'=>$amount,'source_currency'=>'VND','payout_amount_minor'=>$amount,'status'=>$paidOut?'SUCCEEDED':'PROCESSING','provider_payout_ref'=>$paidOut?'DEMO-NOT-TRANSFER-'.$code:null,'evidence_reference'=>$paidOut?'DEMO - simulated payout, no money moved':null,'failure_reason'=>$paidOut?null:'DEMO_NO_MONEY_MOVED','created_at'=>$ended,'completed_at'=>$paidOut?$ended:null]);
