    public function freshOffers(string $batch,int $count=3):array{
        if(!$this->db->inTransaction())throw new LogicException('Fresh demo orders require a transaction.');
        $q=$this->db->prepare("SELECT new_value FROM audit_logs WHERE action='DEMO_DATASET_CREATED' AND new_value->>'batch'=?");$q->execute([$batch]);$raw=$q->fetchColumn();if(!$raw)throw new RuntimeException('Seed this demo batch first.');$seed=json_decode($raw,true,512,JSON_THROW_ON_ERROR);
        $shipper=(int)$seed['users']['an']['id'];$customer=(int)$seed['users']['customer']['id'];if(!DemoMode::user($this->db,$shipper)||!DemoMode::user($this->db,$customer))throw new RuntimeException('Demo identities required.');
        $this->db->prepare('SELECT user_id FROM shipper_profiles WHERE user_id=? FOR UPDATE')->execute([$shipper]);
        $q=$this->db->prepare("SELECT order_id FROM order_assignments WHERE shipper_id=? AND assignment_status='ACTIVE'");$q->execute([$shipper]);if($active=$q->fetchColumn())return ['active_order_id'=>(int)$active,'offers_created'=>0];
        $q=$this->db->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY order_id LIMIT 1');$q->execute([$customer]);$template=$q->fetch();
        if(!$template||!str_starts_with($template['order_code'],'DEMO-'))throw new RuntimeException('Demo template missing.');
        $this->db->prepare('UPDATE shipper_profiles SET availability=TRUE,last_latitude=10.7769,last_longitude=106.7009,last_location_at=now(),last_active_at=now() WHERE user_id=?')->execute([$shipper]);
        $rows=[];for($n=0;$n<max(1,min(5,$count));$n++){
            $data=$template;unset($data['order_id']);$key=bin2hex(random_bytes(6));$data['order_code']='DEMO-'.substr($batch,4).'-LIVE-'.strtoupper($key);$data['status']='PENDING_PAYMENT';$data['quote_id']=null;$data['request_key']='demo-live-'.$key;$data['cancellation_fee_minor']='0';
            foreach(['paid_at','picked_up_at','completed_at','closed_at','cancelled_at'] as $field)$data[$field]=null;
            $data['created_at']=gmdate(DATE_ATOM);$data['updated_at']=$data['created_at'];$id=$this->insert('orders','order_id',$data);
            OrderLifecycleService::history($this->db,$id,null,'PENDING_PAYMENT',$customer,'CUSTOMER','DEMO - fresh offer seed');
            OrderLifecycleService::event($this->db,$data+['order_id'=>$id],'OrderCreated','demo-fresh-created:'.$id);
            (new PaymentService($this->db))->create($customer,$id,'GATEWAY','demo-live-pay-'.$key);
            $match=(new MatchingService($this->db))->dispatch($id);$rows[]=['order_id'=>$id,'order_code'=>$data['order_code'],'matching'=>$match];
        }
        AuditService::record($this->db,null,'SYSTEM','DEMO_OFFERS_CREATED','DEMO_DATASET',null,[],['batch'=>$batch,'orders'=>$rows]);return ['orders'=>$rows,'offers_created'=>array_sum(array_column(array_column($rows,'matching'),'offers'))];
    }

